  ('sao-paulo-brazil', '10S', 'São Paulo, Brazil', 'Brazil', 'The Southern Hemisphere''s largest city', 'live', 'verified', 'venice', 'Rio & The Southeast Coast', '{"romance","culture"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":null,"safety":{"emergency":"190","emergency_medical":"192","advisory_level":"L2","advisory_source":"https://travel.state.gov/content/travel/en/traveladvisories/traveladvisories/brazil-travel-advisory.html","book_enabled":true,"bin":"freely bookable (L2)","consent_flow":false,"air_access_verified":{"international":"GRU (Guarulhos / São Paulo–Guarulhos International — Brazil''s largest)","domestic":"CGH (Congonhas — domestic + regional, close to city core)"},"water":"tap treated/generally potable; visitors commonly drink bottled/filtered","trauma":"Albert Einstein (#1 Latin America, top-30 world) + Sírio-Libanês (#2 Latin America) for stabilization; US medical evacuation for serious cases","caveats":["Favelas / informal housing developments = L4 Do Not Travel, even on guided tours","Crime + kidnapping risk indicators (Brazil-wide)","District-driven urban crime: safe core = Jardins/Itaim Bibi/Paulista/Pinheiros/Vila Madalena","Centro (old downtown) = daytime-only mission; leave before dark","Cracolândia (Luz / Campos Elíseos) = avoid entirely, day or night","Phone-snatching / anti-snatch discipline in crowds","Date-drug / drink-spiking robberies (Brazil advisory)","Vetted transport only after dark (Uber / registered taxi; not municipal buses at night)","Dengue precautions (repellent)"],"fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel Amazonas State FCDO advises against all but essential travel to the following river areas towards the west of Amazonas State: along the Amazonas (Amazon) River and its tributaries west of the town of Codajás and east of the town of Belém do Solimões in Amazonas State along any part of the Itaquaí River in Amazonas State along any part of the Japurá River or its tributaries in Amazonas State along the Rio Negro (Black River) and its tributaries north or west of the town of Barcelos in Amazonas State Find out more about why FCDO advises against travel ."},{"form":"against all but essential travel","text":"advises against all but essential travel: along the Amazonas (Amazon) River and its tributaries west of the town of Codajás and east of the town of Belém do Solimões in Amazonas State along any part of the Itaquaí River in Amazonas State along any part of the Japurá River or its tributaries in Amazonas State along the Rio Negro (Black River) and its tributaries north or west of the town of Barcelos in Amazonas State There are risks to travellers in river areas towards the west of Amazonas State, where Brazil shares borders with Colombia, Peru and Venezuela, due to criminal activity."}],"url":"https://www.gov.uk/foreign-travel-advice/brazil","read":"2026-08-19","page_updated":"2026-05-11T12:32:48+01:00"}},"timing":{"peak":"Year-round (business + trade fairs — WTM Latin America mid-April; MICE all cycle)","inflection":"~3–4 weeks before each event spike (F1: mid-October; Carnaval: mid-January)","fire_date":"curve-start − 1–2 weeks → late September / early October for the F1 spike; early January for Carnaval; culinary-weekend layer fires any month (attach to curve as gateway/stopover)","shoulder":"Rolling culinary-weekend + design-hotel layer, any month","low":"Jun–Aug (austral winter — cooler, drier, comfortable for a food-and-art city); off-season fill with culinary + museum + design-hotel weekends","event_peaks":[{"event":"Formula 1 São Paulo Grand Prix (Interlagos)","dates":"2026-11-06 to 2026-11-08","note":"hotels tighten across race week; travelers stay in city core (~25km from circuit)"},{"event":"Carnaval 2026 (street blocos + Sambódromo do Anhembi)","dates":"2026-02-13 to 2026-02-17","note":"630 blocos programmed; SP does not surcharge as hard as Rio, Sambódromo ~40–60% cheaper — value-Carnaval angle"}]},"jewels":[{"name":"A Casa do Porco","si_tag":"culinary","tier":"comfort","source":"https://www.theworlds50best.com/latinamerica/en/the-list/a-casa-do-porco.html","timing":"Year-round","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Jefferson Rueda''s pork-gospel tasting house, arguably Brazil''s most famous restaurant; a ~US$40 tasting menu, no dress code, ranked 25 in Latin America''s 50 Best","si":"culinary","blurb":"Jefferson Rueda''s pork-gospel tasting house, arguably Brazil''s most famous restaurant; a ~US$40 tasting menu, no dress code, ranked 25 in Latin America''s 50 Best","when":"Year-round","commission":"DMC culinary program carries margin; table booked direct / non-commissionable"},{"name":"D.O.M. (Alex Atala, 2 Michelin stars)","si_tag":"culinary","tier":"ultra","source":"https://guide.michelin.com/en/article/dining-out/all-michelin-starred-restaurants-in-sao-paulo","timing":"Year-round","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","when":"Year-round","commission":"DMC culinary program for margin; table direct"},{"name":"Evvai & Tuju (first Latin American 3 Michelin stars)","si_tag":"culinary","tier":"ultra","source":"https://guide.michelin.com/en/article/dining-out/all-michelin-starred-restaurants-in-sao-paulo","timing":"Year-round","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","when":"Year-round","commission":"DMC / concierge access for margin; table direct"},{"name":"Maní (Helena Rizzo, 1 Michelin star)","si_tag":"culinary","tier":"premier","source":"https://guide.michelin.com/en/article/dining-out/all-michelin-starred-restaurants-in-sao-paulo","timing":"Year-round","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","when":"Year-round","commission":"DMC culinary program for margin; table direct"},{"name":"Mercadão — Municipal Market + mortadella sandwich","si_tag":"culinary","tier":"essential","source":"https://streetsmartbrazil.com/sao-paulos-mercadao-municipal-market-meeting-place/","timing":"Year-round","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the eclectic 1933 market hall under stained glass; the fist-sized mortadella sandwich is the pilgrimage bite, plus pastel de bacalhau and tropical-fruit stalls","si":"culinary","blurb":"the eclectic 1933 market hall under stained glass; the fist-sized mortadella sandwich is the pilgrimage bite, plus pastel de bacalhau and tropical-fruit stalls","when":"Year-round","commission":"food-tour affiliate (GetYourGuide/Viator); entry free"},{"name":"Liberdade — Japanese quarter + weekend fair","si_tag":"culinary","tier":"essential","source":"https://www.tripadvisor.com/Attraction_Review-g303631-d2350042-Reviews-Liberdade_Street_Market-Sao_Paulo_State_of_Sao_Paulo.html","timing":"year-round","timing_type":"ALWAYS-ON","hook":"the largest Japanese community outside Japan; torii gate, red lanterns, weekend arts-and-food fair, sushi counters and Okinawan bakeries. A culinary + cultural double-header","si":"culinary","blurb":"the largest Japanese community outside Japan; torii gate, red lanterns, weekend arts-and-food fair, sushi counters and Okinawan bakeries. A culinary + cultural double-header","when":"year-round","commission":"food/culture-tour affiliate; self-guided free"},{"name":"MASP + Avenida Paulista (Sunday car-free)","si_tag":"culture","tier":"essential","source":"https://www.kupi.com/en/explore/brazil/sao-paulo/sao-paulo-museum-of-art","timing":"Year-round","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Lina Bo Bardi''s icon floating on red pillars over the avenue, holding Rembrandt, Van Gogh, Renoir, Picasso and a deep Brazilian collection","si":"culture","blurb":"Lina Bo Bardi''s icon floating on red pillars over the avenue, holding Rembrandt, Van Gogh, Renoir, Picasso and a deep Brazilian collection","when":"Year-round","commission":"culture-tour affiliate; MASP entry non-commissionable"},{"name":"Pinacoteca + Farol Santander view","si_tag":"culture","tier":"essential","source":"https://www.nomadicmatt.com/travel-guides/brazil-travel-tips/sao-paulo/","timing":"Year-round","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the city''s oldest art museum, the great collection of Brazilian works, paired with the Farol Santander observation deck for the skyline","si":"culture","blurb":"the city''s oldest art museum, the great collection of Brazilian works, paired with the Farol Santander observation deck for the skyline","when":"Year-round","commission":"culture-tour affiliate; entries non-commissionable"},{"name":"Ibirapuera Park + Oscar Niemeyer (Oca / MAC / Afro-Brasil)","si_tag":"culture","tier":"essential","source":"https://www.nomadicmatt.com/travel-guides/brazil-travel-tips/sao-paulo/","timing":"Year-round","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"South America''s great urban park, the Niemeyer-designed Oca, Auditório and MAC/Afro-Brasil museums; footvolley, bike paths, and modernist architecture in one green sweep","si":"culture","blurb":"South America''s great urban park, the Niemeyer-designed Oca, Auditório and MAC/Afro-Brasil museums; footvolley, bike paths, and modernist architecture in one green sweep","when":"Year-round","commission":"culture-tour affiliate / self-guided; museum entries non-commissionable"},{"name":"Beco do Batman street art (Vila Madalena)","si_tag":"culture","tier":"essential","source":"https://www.tripadvisor.com/Attraction_Review-g303631-d2349935-Reviews-Batman_Alley-Sao_Paulo_State_of_Sao_Paulo.html","timing":"Year-round","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Crowds, phone-snatching around the alley, night caution Daytime unguided fine; guided street-art tour adds context; keep the phone secured","si":"culture","blurb":"Crowds, phone-snatching around the alley, night caution Daytime unguided fine; guided street-art tour adds context; keep the phone secured","when":"Year-round","commission":"street-art walking-tour affiliate; self-guided free (daytime)"},{"name":"Vila Madalena bar night","si_tag":"romance","tier":"essential","source":"https://www.leftturnstravel.com/post/neighborhood-guide-to-vila-madalena","timing":"Year-round","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the bohemian nightlife epicenter: Astor, Pé de Manga, Bar do Baixo, Pracinha do Seu Justino","si":"romance","blurb":"the bohemian nightlife epicenter: Astor, Pé de Manga, Bar do Baixo, Pracinha do Seu Justino","when":"Year-round","commission":"nightlife / bar-crawl tour affiliate; DMC private evening"},{"name":"Helicopter skyline tour (Campo de Marte)","si_tag":"romance","tier":"premier","source":"https://passeiodehelicoptero.com/en/helicopter-tour-sao-paulo/","timing":"Year-round","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Operator air-safety, weather windows, boarding logistics Guided only — licensed, insured operator; confirm the flight departs Campo de Marte and includes transfer","si":"romance","blurb":"Operator air-safety, weather windows, boarding logistics Guided only — licensed, insured operator; confirm the flight departs Campo de Marte and includes transfer","when":"Year-round","commission":"helicopter-tour affiliate (GetYourGuide/Viator) / DMC"}],"faq":null,"seo":{"meta_title":"São Paulo Travel Guide 2026 — Latin America''s Food Capital, MASP, Ibirapuera & Design Hotels | TravelWell","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","search_language":"pt-BR","local_keywords":["o que fazer em São Paulo","melhores restaurantes SP","MASP Avenida Paulista","Ibirapuera o que fazer","Beco do Batman Vila Madalena","Mercadão sanduíche de mortadela","bairro da Liberdade São Paulo","São Paulo é seguro para turistas","onde ficar em São Paulo Jardins Itaim","melhores hotéis de luxo em São Paulo","passeio de helicóptero São Paulo"],"hreflang":["en","pt-BR"]},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"name":"Rosewood São Paulo (Cidade Matarazzo)","lane":"Virtuoso/Fora","mor":"consortia","tier":"ultra","note":"Jean Nouvel + Philippe Starck; the flagship opening"},{"name":"Palácio Tangará","lane":"Virtuoso/Fora","mor":"consortia","tier":"ultra","note":"Oetker Collection; Parque Burle Marx"},{"name":"Fasano São Paulo","lane":"Virtuoso/Fora","mor":"consortia","tier":"ultra","note":"Jardim Paulista; Baretto live-music room"},{"name":"Hotel Unique","lane":"consortia/Fora","mor":"consortia","tier":"ultra","note":"Ruy Ohtake half-moon landmark; Skye rooftop"},{"name":"Four Seasons São Paulo","lane":"FSPP/consortia","mor":"consortia","tier":"ultra","note":"business-district brand-loyalty anchor"}],"source_verified":null,"hero":{"query":"São Paulo, Brazil, Brazil"},"geo":{"lat":-23.5558,"lng":-46.6396}}'::jsonb, 104),
  ('sayulita-mexico', '10S', 'Sayulita & the Riviera Nayarit', 'Mexico', 'Nayarit''s boho surf pueblo magico', 'live', 'verified', 'tropicalBeach', 'Nayarit (Riviera Nayarit & Sayulita)', '{"tropical","expedition","romance","ocean","culture","family","wildlife"}', '{"tropical"}', '{"essential","comfort","luxury"}', null, null, '{"key_facts":["Sayulita is a Pueblo Magico (since 2015) and the boho surf-and-art anchor of the southern Riviera Nayarit.","Bahia de Banderas filters Pacific swell into a forgiving 2-4 ft sand-bottom beach break - one of Mexico''s best beginner surf classrooms.","Islas Marietas ''hidden beach'' (Playa del Amor) is permit-capped: ~116 people/day, closed Mondays and Tuesdays, licensed operators only, no self-swim, life jacket + no fins, no under-10s or over-65s.","Humpback whales fill Banderas Bay roughly mid-December to early April, peak January-February.","Sayulita''s rapid growth outran its sewage infrastructure; major upgrades and an offshore outfall have been built, beach under permanent sanitary surveillance - drink bottled water, swim the protected Los Muertos cove.","Air access via Puerto Vallarta International (PVR), ~24 miles / 38-60 min south."],"safety":{"emergency":"911","hospital":"Nearest full trauma: Puerto Vallarta private hospitals (CMQ / San Javier / Hospital Joya), ~40-60 min south; local Sayulita/Bucerias clinics stabilize/transfer; complex cases PVR -> US/Guadalajara air-evac","advisory_level":"L2","book_enabled":true,"bin":"freely bookable (L2)","air_access_verified":true,"air_access_note":"Puerto Vallarta International (PVR), ~24 mi / 38-60 min south, in Jalisco but the regional gateway","riptides":"main beach + Los Muertos mellow; Patzcuarito/Carricitos open-Pacific and rip-prone (unsafe for beginner swimmers)","water":"bottled/purified only","dengue":"endemic seasonal risk, higher May-November","malaria":"not a practical risk in the tourist corridor","hurricane":"Pacific storm season ~June-October; insure/refundable summer rates","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"peak":"Dec-Apr (dry season; whales Dec-Mar peak Jan-Feb; surf year-round; highest rates + crowds)","inflection":"November (dry weather arrives, thinner crowds, whales opening) and late April (emptying out)","green":"May-Oct (rainy/value; ~20-40% off; warmest ocean; calm beginner surf)","holiday_event_peaks":["Christmas week","New Year","Semana Santa (late Mar/early Apr - verify calendar)"],"booking_window_lead_time":"peak/holiday 3-5 months; shoulder (Nov/late-Apr) 2-4 months; green season near-walk-up","fire_date":"curve-start minus 1-2 weeks: open peak (Dec-Apr) campaigns early October; whale-season push early November; Semana Santa campaign by mid-January; green-season value push ~2 weeks before the May shoulder edge","fill_the_beds":"green months: lead beginner surf (calmest/warmest water), long-stay villa value, yoga/wellness retreats, Huichol workshops, San Pancho calm; hedge whale messaging until December"},"jewels":[{"name":"Sayulita main beach + Calle Delfines flag street","si_tag":"Tropical / Beaches","status":"live","tier":"essential","hook":"The town''s surf-beach heart under hundreds of papel-picado flags - go early.","bookable_category":"village stay + surf lesson","source":"https://themexicoedit.com/things-to-do-in-sayulita-mexico/","si":"Tropical / Beaches","blurb":"The town''s surf-beach heart under hundreds of papel-picado flags - go early.","commission":"boutique-AOR + surf-operator affiliate; beach access pass-through"},{"name":"Playa de los Muertos (family swimming cove)","si_tag":"Family","status":"future","tier":"essential","hook":"Rock-protected roped swim area, no surf/boat traffic - the safe kids'' beach.","bookable_category":"villa/boutique stay","source":"https://www.sayulitalife.com/sayulita-beaches","si":"family","blurb":"Rock-protected roped swim area, no surf/boat traffic - the safe kids'' beach.","commission":"villa MoR / boutique-AOR; access pass-through"},{"name":"Beginner surf lesson (sand-bottom break)","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","hook":"Mexico''s best beginner classroom - forgiving filtered 2-4 ft waves.","bookable_category":"surf lesson","source":"https://wildmex.com/activities/surf-lessons-sayulita-mexico/","si":"expedition","blurb":"Mexico''s best beginner classroom - forgiving filtered 2-4 ft waves.","commission":"surf-operator affiliate / referral"},{"name":"Huichol (Wixarika) art galleries + workshop","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"Authentic beadwork/yarn-painting galleries and workshops with the stories behind the symbols.","bookable_category":"gallery + workshop","source":"https://www.roughguides.com/articles/sacred-sites-and-unique-art-supporting-indigenous-huichol-culture/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Authentic beadwork/yarn-painting galleries and workshops with the stories behind the symbols.","when":"Dec-Apr","commission":"workshop affiliate; gallery purchases pass-through"},{"name":"Islas Marietas hidden beach (Playa del Amor)","si_tag":"Ocean Adventures","status":"future","tier":"comfort","hook":"Permit-capped national-park cove reached by swimming through a rock opening; booby colonies.","bookable_category":"licensed boat tour (permit required)","source":"https://wildmex.com/activities/tours-islas-marietas-playa-del-amor/","si":"ocean","blurb":"Permit-capped national-park cove reached by swimming through a rock opening; booby colonies.","commission":"licensed-tour affiliate / DMC; permit ~US$3-5 pass-through"},{"name":"Banderas Bay whale watching","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"Morning humpback tours in the calving bay, Dec-Mar, peak Jan-Feb.","bookable_category":"whale-watch tour","source":"https://cms.vallartalifestyles.com/humpback-whale-season-begins-in-banderas-bay-and-beyond/","si":"wildlife","blurb":"Morning humpback tours in the calving bay, Dec-Mar, peak Jan-Feb.","commission":"affiliate 4-8% / DMC"},{"name":"San Pancho (San Francisco) — quiet-luxe + La Patrona polo","si_tag":"Romance & Honeymoons","status":"live","tier":"luxury","hook":"Slower, upmarket neighbor with polo (Oct-May), arts, wellness - a calm villa/honeymoon alternative.","bookable_category":"luxe villa + polo experience","source":"https://mexiconewsdaily.com/mexico-living/play-the-sport-of-kings-in-laid-back-san-pancho-nayarit/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"Slower, upmarket neighbor with polo (Oct-May), arts, wellness - a calm villa/honeymoon alternative.","when":"Dec-Apr","commission":"DMC / luxury-villa MoR; polo affiliate"},{"name":"Bucerias Thursday Art Walk","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"~17 galleries open 7-9pm Thursdays, artists creating live; quieter than Sayulita.","bookable_category":"art walk + DMC transfer/dinner","source":"https://bestofbucerias.com/nearby/la-cruz-de-huanacaxtle/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"~17 galleries open 7-9pm Thursdays, artists creating live; quieter than Sayulita.","when":"Dec-Apr","commission":"DMC transfer + dining affiliate; walk pass-through"},{"name":"La Cruz de Huanacaxtle marina + Sunday Market","si_tag":"Ocean Adventures","status":"future","tier":"comfort","hook":"The Riviera''s largest artisan market on the marina docks (Sun, Nov-Apr) + sailing/charters hub.","bookable_category":"market + charter","source":"https://www.rivieranayaritfun.com/la-cruz-sunday-market-la-cruz-mercado","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"The Riviera''s largest artisan market on the marina docks (Sun, Nov-Apr) + sailing/charters hub.","when":"Dec-Apr","commission":"charter/DMC; market pass-through"},{"name":"Rincon de Guayabitos family beach","si_tag":"Family","status":"future","tier":"essential","hook":"Old-school calm-water Mexican-family beach town off the surf-tourist track.","bookable_category":"local hotel + DMC transfer","source":"https://lacasitadelapenita.com/activities/markets-in-our-area/","si":"family","blurb":"Old-school calm-water Mexican-family beach town off the surf-tourist track.","commission":"DMC transfer / host-AOR; beach pass-through"}],"faq":[{"q":"What''s the real risk to plan for?","a":"Water and rip currents, not crime. Sayulita''s rapid growth outran its sewage plant — major upgrades and an offshore outfall have since been built and the beach is under permanent sanitary surveillance, but drink only bottled water. Swim the protected coves (main beach, Los Muertos); exposed Patzcuarito/Carricitos are rip-prone and unsafe for beginner swimmers.","source":"globalpressjournal.com / sayulitalife.com, 2026-07-07","si_tag":"safety"},{"q":"How good is Sayulita for learning to surf?","a":"It''s arguably Mexico''s best beginner classroom. Bahía de Banderas filters swell into a forgiving 2–4 ft sand-bottom break where you fall onto soft sand in waist-deep water, and surf works year-round (calmest and warmest in the green season). Take a lesson before attempting the reef/rock point breaks.","source":"mexicotravelandleisure.com / sayulitalife.com, 2026-07-07","si_tag":"expedition"},{"q":"How do I visit the Islas Marietas Hidden Beach?","a":"Licensed operator only — you cannot swim or kayak in on your own. Access is capped at ~116/day, closed Mondays and Tuesdays, with life jacket and no fins mandatory and no children under 10 or adults over 65; you enter by jumping from the boat through a low rock opening. Book weeks ahead in season.","source":"vallartabyowner.com, 2026-07-07","si_tag":"ocean-adventures-—-future"},{"q":"What''s the Huichol art scene about?","a":"Living Indigenous art you can watch being made. Sayulita has deep Wixárika ties: galleries such as Galería Tanana (artist Cilau Valadez) and Tierra Huichol sell authentic beadwork and yarn paintings, and small workshops teach the beading and the meaning of the symbols. Gallery purchases are pass-through; workshops are the bookable wrapper.","source":"roughguides.com, 2026-07-07","si_tag":"culture-&-heritage-—-future"}],"seo":{"meta_title":"Sayulita & Riviera Nayarit Travel Guide 2026 — Surf, Marietas & Where to Stay | TravelWell.World","meta_description":"Plan Sayulita, Nayarit''s boho surf pueblo magico: beginner surf, Islas Marietas hidden-beach permit rules, whale season, Huichol art, straight water-infrastructure notes, Level 2 safety, and San Pancho/Bucerias/La Cruz jewels.","slug":"sayulita-mexico","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-07","search_language":"es-MX","local_keywords":["qué hacer en Sayulita","Islas Marietas playa escondida","Riviera Nayarit","mejor época para visitar Sayulita","clases de surf en Sayulita","arte huichol Sayulita","San Pancho Nayarit","ballenas Bahía de Banderas","Playa de los Muertos Sayulita","villas en Sayulita"],"hreflang":["en","es-MX"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"Tropical / Beaches","status":"live"},{"si":"expedition","status":"live"},{"si":"romance","status":"live"},{"si":"ocean","status":"future"},{"si":"culture","status":"future"},{"si":"family","status":"future"},{"si":"wildlife","status":"future"}],"ultra":[{"name":"Punta Mita — Four Seasons / St. Regis (own dossier)","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso (Fora-eligible)","mor_posture":true,"note":"nearest branded ultra, ~25-30 min south; cross-ref its own dossier","source":"https://www.dreamexoticrentals.com/properties/LatinAmerica/mexico/PuntaMitaMexico-vacation-villas.htm"},{"name":"Amor Boutique Hotel / The Original Villa Amor (Sayulita)","price_tier":"luxury","virtuoso":false,"earning":"boutique-direct / host-AOR","mor_posture":true,"note":"31 oceanfront-hillside villas w/ plunge pools; on-village luxe anchor","source":"https://www.sayulitalife.com/amor-group-boutique-hotels"},{"name":"Haramara Retreat (Sayulita)","price_tier":"luxury","virtuoso":false,"earning":"retreat-direct / host-AOR","mor_posture":true,"note":"off-grid cliff-top wellness casitas, 360 yoga, open-air spa","source":"https://www.bontraveler.com/best-hotels-sayulita-mexico/"},{"name":"San Pancho luxe private villas","price_tier":"ultra","virtuoso":false,"earning":"on application / luxury-DMC or host villa AOR","mor_posture":true,"note":"full-service private villas in quiet-luxe neighbor; net-rate resale red","source":"https://www.puntademita-realestate.com/villasayulita18/"}],"source_verified":"2026-07-07","hero":{"query":"Sayulita & the Riviera Nayarit, Mexico"},"geo":{"lat":20.8697,"lng":-105.4419}}'::jsonb, 105),
  ('semuc-champey-guatemala', '10S', 'Semuc Champey', 'Guatemala', 'Turquoise pools on a natural limestone bridge', 'live', 'verified', 'mountainValley', 'Guatemala', '{"expedition"}', '{}', '{"essential"}', 'essential', null, '{"key_facts":["Pools sit atop a natural limestone bridge over the Cahabón River, which flows beneath them; Q''eqchi'' Maya ''where the river hides under the earth''.","Dry season Nov-Apr = clearest turquoise + safe current; rainy season May-Oct can turn pools brown and flood/close the site.","Lanquín-Semuc access road fully paved (concreted) in 2025; ~20-25 min by 4x4 from Lanquín.","Park open daily 08:00-16:00; entry Q50 foreigner / Q30 national (non-commissionable).","Nearest real hospital ~4 hours away in Cobán — remote-medevac destination."],"safety":{"emergency":{"police":"110","fire_ambulance":"122","proatur_asistur":"1500 / +502 2290 2810","asistur_whatsapp":"+502 5188 1819","red_cross":"125"},"book_enabled":true,"consent_flow":{"bin":"BOOK WITH WARNING","disclosure_required":true,"renders":"full verbatim live US State Dept advisory for the country (level + reason + named-danger areas + complete ''If you decide to travel'' guidance), pulled live, plus traveler acknowledgment","wording_status":"hook set only — final consent language PENDING compliance-attorney sign-off"},"l3_disclosure":true,"state_dept_carveout":"Alta Verapaz not among the four named L4 zones (San Marcos, Huehuetenango, Zone 18, Villa Nueva); route via Cobán/Lanquín reads clean/normal-tourist","stay_in_zone":true,"air_access_verified":"via La Aurora GUA (Guatemala City) then overland Cobán-Lanquín","remote_flag":true,"remote_flag_detail":"HARD — nearest real hospital ~4 hrs away via Cobán → Guatemala City air-evac; evac-grade travel insurance mandatory; K''anba cave guided-only, no PPE; occasional protester roadblocks (consult PROATUR)","founder_policy_note":"BOOK WITH WARNING (Four-Bin v3) — founder-blessed as bookable-with-warning, with mandatory full-advisory disclosure"},"timing":{"season_shape":"dry-season destination (Nov-Apr); pools clearest & safest, road passable","curve_start":"early-to-mid November","peak":"December-March","shoulder_green":["April","late Oct / early Nov"],"off_season":"May-October (water clarity + closure risk)","booking_lead":"2-6 weeks in peak (pressure is on limited Lanquin lodge beds, not the park)","events":"regional: Cobán Rabín Ajau folkloric festival (late Jul/early Aug, rainy season)","fire_date":"~2026-10-20 to 2026-10-27 (curve-start minus 1-2 weeks)","note":"sharpen on live tracking — curve is weather/water-coupled"},"jewels":[{"name":"Turquoise pool terraces","si_tag":"expedition","tier":"essential","source":"https://www.roadaffair.com/the-ultimate-guide-to-visiting-semuc-champey/ (Accessed 2026-07-06)","timing":"December-March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"December-March","commission":"day-tour + lodge + DMC transfer commissionable; park entry non-commissionable","accessed":"2026-07-06"},{"name":"El Mirador viewpoint","si_tag":"expedition","tier":"essential","source":"https://www.roadaffair.com/the-ultimate-guide-to-visiting-semuc-champey/ (Accessed 2026-07-06)","timing":"year-round","timing_type":"ALWAYS-ON","hook":"the postcard shot of the whole terrace chain from above; GEA/photography","si":"expedition","blurb":"the postcard shot of the whole terrace chain from above; GEA/photography","when":"year-round","commission":"bundled in guided day-program","accessed":"2026-07-06"},{"name":"K''anba candlelit caves (tubing)","si_tag":"expedition","tier":"essential","source":"https://www.getyourguide.com/guatemala-city-l1654/from-lanquin-semuc-champey-park-and-kanba-cave-guided-tour-t30495/ (Accessed 2026-07-06)","timing":"December-March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"December-March","commission":"guided day-tour via Viator/GetYourGuide/DMC; community cave fee non-commissionable","accessed":"2026-07-06"},{"name":"Lanquín Caves bat exodus (Grutas de Lanquín)","si_tag":"Wildlife/GEA","tier":"essential","source":"https://sallysees.com/semuc-champey-lanquin-guatemala/ (Accessed 2026-07-06)","hook":"Wildlife/GEA; thousands of bats stream out at sundown","si":"Wildlife/GEA","blurb":"Wildlife/GEA; thousands of bats stream out at sundown","commission":"add-on guided tour via lodge/DMC","accessed":"2026-07-06"},{"name":"Cahabón river tubing","si_tag":"expedition","tier":"essential","source":"https://www.adventurouskate.com/my-favorite-day-in-central-america-semuc-champey/ (Accessed 2026-07-06)","timing":"December-March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"December-March","commission":"outfitter/lodge day-tour (dry season only)","accessed":"2026-07-06"},{"name":"Las Marías village + cacao/chocolate workshop","si_tag":"Culture/Wellness","tier":"essential","source":"https://utopiaecohotel.com/ (Accessed 2026-07-06)","timing":"December-March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Culture/Wellness cross-cut; Q''eqchi'' community + Utopia''s working cacao farm chocolate-making","si":"Culture/Wellness","blurb":"Culture/Wellness cross-cut; Q''eqchi'' community + Utopia''s working cacao farm chocolate-making","when":"December-March","commission":"lodge-run experience (Utopia)","accessed":"2026-07-06"}],"faq":[{"q":"When is the best time to visit Semuc Champey?","a":"The dry season, November–April. That''s when the pools run clearest turquoise, the Cahabón current runs calm enough to swim and tube, and the now-paved road is reliably passable. Rainy season (May–October) can turn the pools muddy brown, spike current danger, and occasionally flood and close the site.","source":"adventurouskate.com, Accessed 2026-07-06","si_tag":"expedition"},{"q":"What wildlife can I see near Semuc?","a":"The signature sight is the Grutas de Lanquín bat exodus, when thousands of bats stream out at sundown — an add-on guided tour via lodge or DMC. The wider department is Alta Verapaz cloud-forest quetzal country, with the Biotopo del Quetzal reserve on the Cobán approach.","source":"sallysees.com, Accessed 2026-07-06","si_tag":"wildlife"},{"q":"What''s the real risk to plan for?","a":"Remoteness. Semuc is deep-rural: the nearest real hospital is ~4 hours away in Cobán, with no trauma center near the pools or caves, so evacuation-grade travel insurance is mandatory doctrine here. Also refuse dangerously overloaded 4×4 transfers (reports of 33 people in one truck) — book transport through a lodge or DMC.","source":"tripadvisor.com, Accessed 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Semuc Champey, Guatemala: Turquoise Pools, Caves & How to Visit (2026 Guide)","search_language":"en + es-GT","local_keywords":["cómo llegar a Semuc Champey","Semuc Champey mejor época para visitar","pozas turquesa Semuc Champey","grutas de Lanquín tour","cuánto cuesta la entrada a Semuc Champey","El Mirador Semuc Champey caminata"],"hreflang":["en","es-GT"],"jsonld_type":"TouristAttraction","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06"},"booking":null,"si_checklist_25":null,"sis_present":["expedition"],"ultra":[{"play":"No true ultra exists; construct it — best eco-lodge (Utopia) or premier Cobán base + fully private guide + private 4x4 transfer, as one adventure day in a luxe Antigua/Atitlan/Tikal circuit","route":"Martsam (mid-luxury DMC) or Fora advisor lane for US ultra clients","manner_of_record":"sell privacy + private guiding, not a nonexistent resort"}],"source_verified":"2026-07-06","hero":{"query":"Semuc Champey, Guatemala"},"geo":{"lat":15.5342,"lng":-89.9539}}'::jsonb, 106),
